    def load(v):
        if isinstance(v, (dict, list)):
            return v
        try:
            return json.loads(v)
        except Exception:
            try:
                return ast.literal_eval(v)
            except Exception:
                return None
    def bank(node):
        d = load(vars.get(node + '_d'))
        if isinstance(d, dict) and d:
            return d
        pre = node + '_response.data.data.'
        root = dict()
        for k in list(vars.keys()):
            if str(k).startswith(pre):
                parts = str(k)[len(pre):].split('.')
                cur = root
                for p in parts[:-1]:
                    cur = cur.setdefault(p, dict())
                cur[parts[-1]] = vars.get(k)
        def fix(x):
            if isinstance(x, dict):
                if x and all(str(k).isdigit() for k in x):
                    return [fix(x[k]) for k in sorted(x, key=int)]
                return dict((k, fix(v)) for k, v in x.items())
            return x
        return fix(root)
