        try:
            return float(x)
        except Exception:
            return 0.0
    def day_of(s):
        s = str(s or '')
        if len(s) == 10 and s[2] == '.':
            return s[6:10] + '-' + s[3:5] + '-' + s[0:2]
        return ''
    def say_date(s):
        s = str(s or '')
        if len(s) != 10 or s[2] != '.':
            return s
        return str(int(s[0:2])) + ' ' + MONTHS[int(s[3:5]) - 1] + ' ' + s[6:10]
