    TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
    DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    def three(n):
        out = []
        h, t, o = n // 100, (n // 10) % 10, n % 10
        if h:
            out.append('yüz' if h == 1 else ONES[h] + ' yüz')
        if t:
            out.append(TENS[t])
        if o:
            out.append(ONES[o])
        return ' '.join(out)
    def words(n):
        n = int(n)
        if n == 0:
            return 'sıfır'
        out = []
        for size, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
            k = n // size
            n = n % size
            if k:
                out.append(name if (k == 1 and name == 'bin') else three(k) + ' ' + name)
        if n:
            out.append(three(n))
        return ' '.join(out)
    def money(x, cur):
        cents = int(round(abs(num(x)) * 100))
        whole, frac = cents // 100, cents % 100
        unit, sub = cur[3], cur[4]
        s = words(whole) + ' ' + unit
        if frac:
            s = s + ' ' + words(frac) + ' ' + sub
        return s
    def digits_say(d):
        return ' '.join(DIG[int(c)] for c in str(d) if c.isdigit())
    def today_iso():
        return str(vars.get('now') or '')[:10]

    kind = str(params.get('kind') or 'other')
    if kind == 'another_card':
        vars['go_pick'] = 'yes'
    elif kind == 'no_other_card' and vars.get('no_debt') == 'yes':
        vars['close_key'] = 'close_done'
    elif kind == 'no_other_card':
        vars['guide'] = 'Say exactly: "' + vars.get('offer_line') + '"'
    elif kind == 'email':
        if vars.get('has_email') == 'yes':
            vars['go_email'] = 'yes'
        else:
            vars['guide'] = 'Say exactly: "' + L['no_email'] + ' ' + L['offer_week'] + '"'
    elif kind == 'past_statement':
        if vars.get('has_email') == 'yes':
            vars['guide'] = 'Say exactly: "' + L['only_latest'] + ' ' + vars.get('email_say') + '" Then, on a yes, call menu_choice with kind email.'
        else:
            vars['guide'] = 'Say exactly: "' + L['no_email'] + ' ' + L['offer_week'] + '"'
    elif kind == 'week':
        vars['go_week'] = 'yes'
    elif kind == 'nothing_else':
        vars['close_key'] = 'close_done'
    else:
        vars['tries'] = int(num(vars.get('tries'))) + 1
        vars['guide'] = 'Say exactly: "' + vars.get('offer_line') + '"'
        if int(num(vars.get('tries'))) >= 3:
            vars['close_key'] = 'close_tries'
    pass
except Exception as exc:
    vars['menu_choice_code_error'] = repr(exc)[:300]

