    def day_of(s):
        s = str(s or '')
        if len(s) == 10 and s[2] == '.':
            return s[6:10] + '-' + s[3:5] + '-' + s[0:2]
        return ''
    def say_date(s):
        s = str(s or '')
        if len(s) != 10 or s[2] != '.':
            return s
        return str(int(s[0:2])) + ' ' + MONTHS[int(s[3:5]) - 1] + ' ' + s[6:10]
    ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
    DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    def three(n):
        out = []
        h, t, o = n // 100, (n // 10) % 10, n % 10
        if h:
            out.append('yüz' if h == 1 else ONES[h] + ' yüz')
        if t:
            out.append(TENS[t])
        if o:
            out.append(ONES[o])
        return ' '.join(out)
    def words(n):
        n = int(n)
        if n == 0:
            return 'sıfır'
        out = []
        for size, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
            k = n // size
            n = n % size
            if k:
                out.append(name if (k == 1 and name == 'bin') else three(k) + ' ' + name)
        if n:
            out.append(three(n))
        return ' '.join(out)
    def money(x, cur):
        cents = int(round(abs(num(x)) * 100))
        whole, frac = cents // 100, cents % 100
        unit, sub = cur[3], cur[4]
        s = words(whole) + ' ' + unit
        if frac:
            s = s + ' ' + words(frac) + ' ' + sub
        return s
    def digits_say(d):
        return ' '.join(DIG[int(c)] for c in str(d) if c.isdigit())
